public final class TrustedLocationLeaseTest {
    static int tests,checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("Remembered location privacy check failed");}
    static final String SELF="AA".repeat(32),OWNER="BB".repeat(32),GROUP="c".repeat(32),ID="d".repeat(32),PROCESS="12345678-1234-1234-1234-123456789abc";
    static final Object SOURCE=new Object();
    static TrustedConnectionScope scope(long generation){return new TrustedConnectionScope(SOURCE,PROCESS,SELF,GROUP,OWNER,3,generation,Arrays.asList(SELF,OWNER),true,true,false);}
    public static void main(String[] args)throws Exception{
        tests++;AtomicBoolean alive=new AtomicBoolean(true),verified=new AtomicBoolean(true);TrustedLocationLease lease=new TrustedLocationLease(ID,1,scope(2),alive::get);Object service=new Object(),pending=new Object();check(lease.begin(scope(2),verified::get,false,null)==null);check(lease.begin(scope(2),verified::get,false,pending)==null);TrustedLocationLease.Activation initial=lease.begin(scope(2),verified::get,true,null);check(initial!=null&&lease.current(initial));check(lease.holdForeground(service));check(!lease.holdForeground(pending));check(lease.holdsForeground(service)&&!lease.holdsForeground(pending));
        tests++;GroupConsent consent=new GroupConsent();long oldRequest=consent.requestEnable();check(consent.grant(oldRequest));LocationOwnership providers=new LocationOwnership();long oldProvider=providers.prepareBackground(ID);check(providers.activateBackground(ID,oldProvider));check(providers.background());check(consent.denyIfCurrent(oldRequest));check(providers.endBackground(ID));check(lease.pause(initial));check(!lease.current(initial)&&!providers.wantsCapture()&&!consent.enabled()&&lease.holdsForeground(service));verified.set(false);check(lease.begin(scope(3),verified::get,false,service)==null);verified.set(true);TrustedLocationLease.Activation restored=lease.begin(scope(3),verified::get,false,service);check(restored!=null&&lease.current(restored));check(!lease.pause(initial)&&lease.current(restored));long newRequest=consent.requestEnable();check(!consent.grant(oldRequest)&&consent.grant(newRequest));check(!consent.denyIfCurrent(oldRequest)&&consent.granted(newRequest));long newProvider=providers.prepareBackground(ID);check(!providers.activateBackground(ID,oldProvider));check(providers.activateBackground(ID,newProvider));
        tests++;TrustedConnectionScope changedEpoch=new TrustedConnectionScope(SOURCE,PROCESS,SELF,GROUP,OWNER,4,3,Arrays.asList(SELF,OWNER),true,true,false);TrustedConnectionScope changedRoster=new TrustedConnectionScope(SOURCE,PROCESS,SELF,GROUP,OWNER,3,3,Arrays.asList(SELF,OWNER,"EE".repeat(32)),true,true,false);TrustedConnectionScope changedProcess=new TrustedConnectionScope(new Object(),"87654321-1234-1234-1234-123456789abc",SELF,GROUP,OWNER,3,3,Arrays.asList(SELF,OWNER),true,true,false);for(TrustedConnectionScope changed:new TrustedConnectionScope[]{changedEpoch,changedRoster,changedProcess}){check(!lease.accepts(changed));check(lease.begin(changed,()->true,false,service)==null);}TrustedLocationLease afterProcessDeath=new TrustedLocationLease(ID,2,scope(3),()->true);check(afterProcessDeath.begin(scope(3),()->true,false,service)==null);
        tests++;AtomicBoolean stopFlag=new AtomicBoolean(true);TrustedLocationLease stopped=new TrustedLocationLease(ID,5,scope(2),stopFlag::get);GroupConsent pendingConsent=new GroupConsent();long pendingGrant=pendingConsent.requestEnable();CountDownLatch captured=new CountDownLatch(1),release=new CountDownLatch(1);AtomicReference<TrustedLocationLease.Activation> late=new AtomicReference<>();AtomicBoolean lateForeground=new AtomicBoolean(true);Thread queued=new Thread(()->{captured.countDown();try{release.await();late.set(stopped.begin(scope(2),()->true,true,null));lateForeground.set(stopped.holdForeground(new Object()));}catch(InterruptedException failure){throw new AssertionError(failure);}});queued.start();check(captured.await(1,TimeUnit.SECONDS));stopFlag.set(false);check(stopped.close());check(pendingConsent.denyIfCurrent(pendingGrant));release.countDown();queued.join(1000);check(!queued.isAlive()&&late.get()==null&&!lateForeground.get()&&!pendingConsent.grant(pendingGrant));TrustedLocationLease replacement=new TrustedLocationLease(ID,6,scope(2),()->true);Object replacementService=new Object();check(replacement.holdForeground(replacementService));stopped.releaseForeground(replacementService);check(replacement.holdsForeground(replacementService));check(!stopped.matches(ID,6));
        tests++;providers.foreground("independent-map-view");check(providers.endBackground(ID));check(providers.ownsForeground("independent-map-view")&&providers.wantsCapture());check(lease.close());check(!lease.current(restored)&&!lease.holdsForeground(service));check(providers.ownsForeground("independent-map-view"));providers.endForeground("independent-map-view");check(!providers.wantsCapture());
        tests++;AtomicBoolean permission=new AtomicBoolean(true);TrustedLocationLease permissionOwner=new TrustedLocationLease(ID,8,scope(2),permission::get);Object permissionService=new Object();check(permissionOwner.holdForeground(permissionService));TrustedLocationLease.Activation allowed=permissionOwner.begin(scope(2),()->true,false,permissionService);check(allowed!=null);permission.set(false);check(!permissionOwner.alive()&&!permissionOwner.current(allowed)&&!permissionOwner.holdsForeground(permissionService));check(permissionOwner.begin(scope(2),()->true,true,null)==null);
        tests++;Object nativeGroup=new Object();LocationActivationGuard.Token tokenA=new LocationActivationGuard.Token(nativeGroup,2,10),tokenB=new LocationActivationGuard.Token(nativeGroup,3,12);LocationActivationGuard nativeSlot=new LocationActivationGuard(tokenA);AtomicBoolean cancelled=new AtomicBoolean();CountDownLatch oldMatched=new CountDownLatch(1),oldFinish=new CountDownLatch(1);AtomicBoolean oldCancelled=new AtomicBoolean(true);Thread oldCancel=new Thread(()->{oldMatched.countDown();try{oldFinish.await();oldCancelled.set(nativeSlot.cancel(tokenA,()->cancelled.set(true)));}catch(InterruptedException failure){throw new AssertionError(failure);}});oldCancel.start();check(oldMatched.await(1,TimeUnit.SECONDS));check(nativeSlot.replace(tokenA,tokenB,()->{}));oldFinish.countDown();oldCancel.join(1000);check(!oldCancel.isAlive()&&!oldCancelled.get()&&!cancelled.get());check(nativeSlot.update(tokenB,()->{}));check(nativeSlot.cancel(tokenB,()->cancelled.set(true)));check(!nativeSlot.replace(tokenB,tokenA,()->{}));
        tests++;GroupConsent concurrentConsent=new GroupConsent();AtomicReference<Object> marker=new AtomicReference<>();Object firstMarker=new Object(),secondMarker=new Object();long revisionA=concurrentConsent.requestEnable();marker.set(firstMarker);CountDownLatch denied=new CountDownLatch(1),clearOld=new CountDownLatch(1);Thread oldCleanup=new Thread(()->{check(concurrentConsent.denyIfCurrent(revisionA));denied.countDown();try{clearOld.await();marker.compareAndSet(firstMarker,null);}catch(InterruptedException failure){throw new AssertionError(failure);}});oldCleanup.start();check(denied.await(1,TimeUnit.SECONDS));long revisionB=concurrentConsent.requestEnable();marker.set(secondMarker);clearOld.countDown();oldCleanup.join(1000);check(!oldCleanup.isAlive()&&marker.get()==secondMarker&&concurrentConsent.current(revisionB));
        tests++;LocationOwnership sameService=new LocationOwnership();long firstActivation=sameService.prepareBackground(ID);check(sameService.activateBackground(ID,firstActivation));check(sameService.endBackground(ID,firstActivation));long replacementActivation=sameService.prepareBackground(ID);check(sameService.activateBackground(ID,replacementActivation));check(!sameService.endBackground(ID,firstActivation)&&sameService.background(ID));check(sameService.endBackground(ID,replacementActivation));
        System.out.println(new JSONObject().put("status","passed").put("testCount",tests).put("assertionCount",checks));
    }
}
